#include <iostream>
using namespace std;

void solve() {
  long long B;
  cin >> B;
  if (B == 1) {
    cout << 1 << endl;
    return;
  }
  for (int A = 2; A <= 20; A++) {
    int x = 0;
    long long y = B;
    while (y % A == 0) x++, y /= A;
    if (x == A && y == 1) {
      cout << A << endl;
      return;
    }
  }
  cout << "-1" << endl;
}

int main() {
  solve();
}
